import{_ as s,l as o,o as e,c as l,v as t,p as n,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"序号与重传","description":"","frontmatter":{"title":"序号与重传","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tcp-seq-rexmit.md","filePath":"cs/tcp-seq-rexmit.md","lastUpdated":1789023840000}'),h={name:"cs/tcp-seq-rexmit.md"};function m(T,a,_,A,E,u){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="序号与重传" tabindex="-1">序号与重传 <a class="header-anchor" href="#序号与重传" aria-label="Permalink to &quot;序号与重传&quot;">​</a></h1><div class="epigraph"><p>每个字节一个序号；累计确认告诉发送方前缀已到。丢了就按定时器或重复确认重发。</p><footer>—— 据 RFC 793；Karn and Partridge, Improving Round-Trip Estimates in Reliable Transport Protocols, 1987 整理</footer></div><p><a href="/cs/tcp-time-wait">上一课</a>同步了 ISN。IP 仍会丢包。<a href="/cs/layering-e2e">端到端</a>要求两端保证字节流。缺口是<strong>序号、累计 ACK、重传</strong>：把数据报变成可靠流的数据平面。本课不把接收窗口与拥塞窗口分开写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>载荷从 ISN+1 起编号。接收方 ACK 表示「期望的下一个字节」。丢失则发送方超时重传；RTO 必须估 RTT，估低了假重传，估高了延迟。Karn：重传段不拿来更新 RTT，避免歧义。缺口不是再握手，而是这条可靠机。</p><p>快速重传：三个重复 ACK 暗示该序号丢了，可不等 RTO。本课点名，与拥塞反应的耦合下一课之后。</p><p><span class="marginnote">累计 ACK 不描述空洞后已到达的段。SACK（RFC 2018）补上块信息，主干先掌握累计语义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发送：切段、填序号、启动该段的计时（实现常一个 RTO 时钟）。接收：按序号写入重组缓冲，交有序前缀给应用，发 ACK。重复段丢弃。校验和失败当丢。与 <a href="/cs/udp">UDP</a> 对照：UDP 把乱序交给应用；TCP 藏在内核里。</p>',9)),(e(),n(c,null,{default:r(()=>[d(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEQ%5B%22%E5%AD%97%E8%8A%82%E5%BA%8F%E5%8F%B7%22%5D%20--%3E%20SEG%5B%22%E5%88%86%E6%AE%B5%E5%8F%91%E9%80%81%22%5D%0A%20%20SEG%20--%3E%20ACK%5B%22%E7%B4%AF%E8%AE%A1%20ACK%22%5D%0A%20%20SEG%20--%3E%20RTO%5B%22%E8%B6%85%E6%97%B6%E6%88%96%E5%BF%AB%E9%87%8D%E4%BC%A0%22%5D%0A%20%20RTO%20--%3E%20SEG%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>序号让迟到的旧连接段（若 ISN 与时间窗配合）可被拒绝；让重复可识别。重传实现端到端文件传输的「最终到」，链路 FCS 只是降丢包率。与<a href="/cs/ipc-pipe">管道</a>对照：管道丢数据只在内核崩溃；TCP 假定中间网络会丢。</p><p>RTO 与<a href="/cs/scheduling-metrics">调度</a>交互：超时线程可能睡醒重发，不占 CPU 忙等。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把时间戳选项与 PAWS 写完。不引入纠删码代替重传。流控（接收方缓冲）与拥塞（网络）尚未拆开：下一课窗口先谈接收方。</p><p>序号 32 位，高速长时间连接要 PAWS 用时间戳防回绕。本课假定窗口内无回绕歧义。</p><p>后课默认：丢失由序号与重传补齐。接收方缓冲有限时发送方必须减速，下一课流控窗口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>字节编号 + 累计 ACK + RTO/快重传 = 可靠前缀。</li><li>Karn 规则处理重传下的 RTT 歧义。</li><li>接收窗口是下一课；网络拥塞是再下一课。</li><li>出处：RFC 793；Karn and Partridge, 1987；Kurose and Ross。</li></ul>',9))])}const P=s(h,[["render",m]]);export{C as __pageData,P as default};
